"use client";

import { cn } from "@/lib/utils";
import { CanvasStage } from "@/registry/ivan/components/canvas-stage/canvas-stage";

import { lunarDitherDefaults } from "./lunar-dither-material";
import { LunarDitherScene } from "./lunar-dither-scene";
import type { LunarDitherSceneProps } from "./lunar-dither-scene";

export interface LunarDitherProps extends LunarDitherSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel = "A cratered moon printed as an ordered dither";

const fallbackDisc = (ink: string, paper: string) =>
  `radial-gradient(circle closest-side, transparent 76%, ${ink} 77%), radial-gradient(circle at 34% 32%, ${paper} 0%, ${ink} 72%)`;

export const LunarDither = ({
  className,
  label = defaultLabel,
  ink = lunarDitherDefaults.ink,
  paper = lunarDitherDefaults.paper,
  paused = lunarDitherDefaults.paused,
  impacts = lunarDitherDefaults.impacts,
  ...sceneProps
}: LunarDitherProps) => (
  <CanvasStage
    className={cn("aspect-square", impacts && "cursor-crosshair", className)}
    fallback={
      <div
        aria-hidden
        className="absolute inset-0"
        style={{ backgroundImage: fallbackDisc(ink, paper) }}
      />
    }
    ground={ink}
    label={label}
    paused={paused}
  >
    {(isAnimating) => (
      <LunarDitherScene
        {...sceneProps}
        impacts={impacts}
        ink={ink}
        paper={paper}
        paused={!isAnimating}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import type { ThreeEvent } from "@react-three/fiber";
import {
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
} from "react";
import type { Ref } from "react";
import {
  MathUtils,
  PerspectiveCamera,
  Sphere,
  SphereGeometry,
  Vector3,
} from "three";
import type { Intersection, Mesh, Object3D, Raycaster } from "three";

import {
  LunarDitherMaterial,
  clampImpactCapacity,
  impactTiming,
  lunarDitherDefaults,
} from "./lunar-dither-material";
import { MeteorStreaks } from "./lunar-dither-streaks";

export interface LunarDitherSceneHandle {
  clearImpacts: () => void;
}

export interface LunarDitherSceneProps {
  ink?: string;
  paper?: string;
  pixelSize?: number;
  grain?: number;
  rotationSpeed?: number;
  craterScale?: number;
  followPointer?: boolean;
  lightDirection?: readonly [number, number, number];
  paused?: boolean;
  impacts?: boolean;
  maxImpacts?: number;
  onImpact?: (point: Vector3) => void;
  ref?: Ref<LunarDitherSceneHandle>;
}

interface MoonLook {
  ink: string;
  paper: string;
  pixelSize: number;
  grain: number;
  craterScale: number;
}

interface MoonFrame {
  cameraPosition: Vector3;
  lightDirection: readonly [number, number, number] | null;
  pointer: { x: number; y: number };
  delta: number;
  dpr: number;
  paused: boolean;
  rotationSpeed: number;
}

const cameraFov = 26;
const moonFill = 0.78;
const axialTilt = 0.12;
const restingTurn = 0.6;
const lightEase = 3.2;
const maxStep = 0.05;
const restingPointer = { x: 0, y: 0.15 };

const lightFromPointer = (x: number, y: number, target: Vector3) => {
  const azimuth = MathUtils.degToRad(MathUtils.clamp(x, -1, 1) * 110 - 55);
  const elevation = MathUtils.degToRad(MathUtils.clamp(y, -1, 1) * 55 + 12);
  return target.set(
    Math.sin(azimuth) * Math.cos(elevation),
    Math.sin(elevation),
    Math.cos(azimuth) * Math.cos(elevation)
  );
};

const hitSphere = new Sphere();
const hitPoint = new Vector3();

const raycastUnitSphere = function raycastUnitSphere(
  this: Object3D,
  raycaster: Raycaster,
  intersects: Intersection[]
) {
  hitSphere.center.setFromMatrixPosition(this.matrixWorld);
  hitSphere.radius = this.matrixWorld.getMaxScaleOnAxis();
  if (!raycaster.ray.intersectSphere(hitSphere, hitPoint)) {
    return;
  }
  const distance = raycaster.ray.origin.distanceTo(hitPoint);
  if (distance < raycaster.near || distance > raycaster.far) {
    return;
  }
  intersects.push({ distance, object: this, point: hitPoint.clone() });
};

const fitMoonCamera = (
  camera: PerspectiveCamera,
  width: number,
  height: number
) => {
  const aspect = width / Math.max(height, 1);
  const halfHeight = Math.tan(MathUtils.degToRad(cameraFov / 2));
  camera.aspect = aspect;
  camera.position.set(0, 0, 1 / (moonFill * halfHeight * Math.min(1, aspect)));
  camera.lookAt(0, 0, 0);
  camera.updateProjectionMatrix();
};

class MoonRig {
  readonly material = new LunarDitherMaterial();
  readonly geometry = new SphereGeometry(1, 160, 120);
  readonly streaks = new MeteorStreaks(this.material.uniforms);
  private readonly toCamera = new Vector3();
  private readonly light = lightFromPointer(
    restingPointer.x,
    restingPointer.y,
    new Vector3()
  );
  private readonly lightTarget = new Vector3();
  private elapsed = 0;

  applyLook({ ink, paper, pixelSize, grain, craterScale }: MoonLook) {
    const { uniforms } = this.material;
    uniforms.uInk.value.set(ink);
    uniforms.uPaper.value.set(paper);
    uniforms.uPixelSize.value = pixelSize;
    uniforms.uGrain.value = grain;
    uniforms.uCraterScale.value = craterScale;
  }

  advance(moon: Mesh | null, frame: MoonFrame) {
    const { uniforms } = this.material;
    if (frame.lightDirection) {
      this.lightTarget.set(...frame.lightDirection).normalize();
    } else {
      lightFromPointer(frame.pointer.x, frame.pointer.y, this.lightTarget);
    }
    if (frame.paused) {
      this.light.copy(this.lightTarget);
    } else {
      const step = Math.min(frame.delta, maxStep);
      this.elapsed += step;
      this.light
        .lerp(this.lightTarget, 1 - Math.exp(-lightEase * step))
        .normalize();
      if (moon) {
        moon.rotation.y += step * frame.rotationSpeed;
      }
    }
    uniforms.uLightDir.value.copy(this.light);
    uniforms.uTime.value = this.elapsed;
    uniforms.uDpr.value = frame.dpr;
    if (moon) {
      this.streaks.advance(this.elapsed, moon, frame.cameraPosition);
    }
  }

  strike(
    direction: Vector3,
    hit: Vector3,
    cameraPosition: Vector3,
    animate: boolean
  ) {
    if (animate) {
      this.toCamera.subVectors(cameraPosition, hit).normalize();
      this.streaks.launch(direction, hit, this.toCamera, this.elapsed);
      this.material.addImpact(direction, this.elapsed + impactTiming.flight);
    } else {
      this.material.addImpact(direction, this.elapsed - impactTiming.settled);
    }
  }

  clearImpacts() {
    this.material.clearImpacts();
    this.streaks.clear();
  }

  dispose() {
    this.material.dispose();
    this.geometry.dispose();
    this.streaks.dispose();
  }
}

const MoonCamera = () => {
  const set = useThree((state) => state.set);
  const get = useThree((state) => state.get);
  const invalidate = useThree((state) => state.invalidate);
  const width = useThree((state) => state.size.width);
  const height = useThree((state) => state.size.height);
  const camera = useMemo(
    () => new PerspectiveCamera(cameraFov, 1, 0.1, 100),
    []
  );

  useLayoutEffect(() => {
    fitMoonCamera(camera, width, height);
    invalidate();
  }, [camera, height, invalidate, width]);

  useLayoutEffect(() => {
    const previous = get().camera;
    set({ camera });
    return () => set({ camera: previous });
  }, [camera, get, set]);

  return null;
};

export const LunarDitherScene = ({
  ink = lunarDitherDefaults.ink,
  paper = lunarDitherDefaults.paper,
  pixelSize = lunarDitherDefaults.pixelSize,
  grain = lunarDitherDefaults.grain,
  rotationSpeed = lunarDitherDefaults.rotationSpeed,
  craterScale = lunarDitherDefaults.craterScale,
  followPointer = lunarDitherDefaults.followPointer,
  lightDirection,
  paused = lunarDitherDefaults.paused,
  impacts = lunarDitherDefaults.impacts,
  maxImpacts = lunarDitherDefaults.maxImpacts,
  onImpact,
  ref,
}: LunarDitherSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const moon = useRef<Mesh>(null);
  const rig = useMemo(() => new MoonRig(), []);

  useEffect(() => () => rig.dispose(), [rig]);

  useEffect(() => {
    rig.material.setImpactCapacity(clampImpactCapacity(maxImpacts));
    rig.streaks.clear();
    invalidate();
  }, [invalidate, maxImpacts, rig]);

  useImperativeHandle(
    ref,
    () => ({
      clearImpacts: () => {
        rig.clearImpacts();
        invalidate();
      },
    }),
    [invalidate, rig]
  );

  const strike = useCallback(
    (event: ThreeEvent<MouseEvent>) => {
      const mesh = moon.current;
      if (!mesh) {
        return;
      }
      event.stopPropagation();
      const direction = mesh.worldToLocal(event.point.clone()).normalize();
      rig.strike(direction, event.point, event.camera.position, !paused);
      onImpact?.(direction.clone());
      invalidate();
    },
    [invalidate, onImpact, paused, rig]
  );

  useEffect(() => {
    rig.applyLook({ craterScale, grain, ink, paper, pixelSize });
    invalidate();
  }, [craterScale, grain, ink, invalidate, paper, pixelSize, rig]);

  useFrame((state, delta) => {
    rig.advance(moon.current, {
      cameraPosition: state.camera.position,
      delta,
      dpr: state.viewport.dpr,
      lightDirection: followPointer ? null : (lightDirection ?? null),
      paused,
      pointer: followPointer ? state.pointer : restingPointer,
      rotationSpeed,
    });
  });

  return (
    <>
      <MoonCamera />
      <group rotation={[0, 0, axialTilt]}>
        <mesh
          geometry={rig.geometry}
          material={rig.material}
          onClick={impacts ? strike : undefined}
          raycast={raycastUnitSphere}
          ref={moon}
          rotation={[0, restingTurn, 0]}
        />
      </group>
      <primitive object={rig.streaks.mesh} />
    </>
  );
};

import { Color, ShaderMaterial, Vector3, Vector4 } from "three";
import type { IUniform } from "three";

export const lunarDitherDefaults = {
  craterScale: 3,
  followPointer: true,
  grain: 0.35,
  impacts: true,
  ink: "#0B0B0C",
  maxImpacts: 32,
  paper: "#EDECE8",
  paused: false,
  pixelSize: 2,
  rotationSpeed: 0.06,
} as const;

export interface LunarDitherUniforms {
  [uniform: string]: IUniform;
  uInk: IUniform<Color>;
  uPaper: IUniform<Color>;
  uLightDir: IUniform<Vector3>;
  uPixelSize: IUniform<number>;
  uTime: IUniform<number>;
  uGrain: IUniform<number>;
  uCraterScale: IUniform<number>;
  uDpr: IUniform<number>;
  uImpacts: IUniform<Vector4[]>;
  uImpactCount: IUniform<number>;
}

export const impactTiming = {
  flight: 0.18,
  settled: 1,
  shockwave: 0.6,
} as const;

const impactCapacityLimit = 64;

export const clampImpactCapacity = (capacity: number) =>
  Math.min(Math.max(Math.round(capacity), 1), impactCapacityLimit);

export const bayerGlsl = `
float bayer2(vec2 a) {
  a = floor(a);
  return fract(dot(a, vec2(0.5, a.y * 0.75)));
}

float bayer4(vec2 a) {
  return bayer2(0.5 * a) * 0.25 + bayer2(a);
}

float bayer8(vec2 a) {
  return bayer4(0.5 * a) * 0.25 + bayer2(a);
}
`;

const vertexShader = `
varying vec3 vObjectPosition;
varying vec3 vWorldPosition;
varying vec3 vWorldNormal;

void main() {
  vObjectPosition = position;
  vec4 world = modelMatrix * vec4(position, 1.0);
  vWorldPosition = world.xyz;
  vWorldNormal = normalize(mat3(modelMatrix) * normal);
  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

const fragmentShader = `
uniform vec3 uInk;
uniform vec3 uPaper;
uniform vec3 uLightDir;
uniform float uPixelSize;
uniform float uTime;
uniform float uGrain;
uniform float uCraterScale;
uniform float uDpr;
uniform vec4 uImpacts[MAX_IMPACTS];
uniform float uImpactCount;

varying vec3 vObjectPosition;
varying vec3 vWorldPosition;
varying vec3 vWorldNormal;

float hash13(vec3 p) {
  p = fract(p * 0.1031);
  p += dot(p, p.zyx + 31.32);
  return fract((p.x + p.y) * p.z);
}

vec3 hash33(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx);
}

float hash12(vec2 p) {
  vec3 q = fract(vec3(p.xyx) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float valueNoise(vec3 p) {
  vec3 i = floor(p);
  vec3 f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  float a = mix(hash13(i), hash13(i + vec3(1.0, 0.0, 0.0)), u.x);
  float b = mix(hash13(i + vec3(0.0, 1.0, 0.0)), hash13(i + vec3(1.0, 1.0, 0.0)), u.x);
  float c = mix(hash13(i + vec3(0.0, 0.0, 1.0)), hash13(i + vec3(1.0, 0.0, 1.0)), u.x);
  float d = mix(hash13(i + vec3(0.0, 1.0, 1.0)), hash13(i + vec3(1.0, 1.0, 1.0)), u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z);
}

float fbm(vec3 p) {
  float sum = 0.0;
  float amplitude = 0.5;
  for (int octave = 0; octave < 4; octave++) {
    sum += amplitude * valueNoise(p);
    p = p * 2.03 + 17.1;
    amplitude *= 0.5;
  }
  return sum;
}

float craterProfile(float x) {
  float bowl = max(min(x * x - 1.0, 0.0), -0.72);
  float rim = 0.3 * exp(-11.0 * (x - 1.0) * (x - 1.0));
  return bowl + rim;
}

float craterField(vec3 p) {
  vec3 cell = floor(p);
  vec3 local = fract(p);
  float height = 0.0;
  for (int z = -1; z <= 1; z++) {
    for (int y = -1; y <= 1; y++) {
      for (int x = -1; x <= 1; x++) {
        vec3 offset = vec3(float(x), float(y), float(z));
        vec3 id = cell + offset;
        vec3 seed = hash33(id);
        float radius = mix(0.16, 0.46, seed.x * seed.x);
        float present = step(0.32, seed.y);
        vec3 center = offset + 0.15 + 0.7 * hash33(id + 7.31);
        float reach = length(local - center) / radius;
        height += present * craterProfile(reach) * radius;
      }
    }
  }
  return height;
}

float surfaceHeight(vec3 p, float maria) {
  float scale = uCraterScale;
  float large = craterField(p * scale) / scale;
  float medium = craterField(p * scale * 2.7 + 3.1) / (scale * 2.7);
  float small = craterField(p * scale * 7.3 + 9.7) / (scale * 7.3);
  float regolith = fbm(p * 26.0) * 0.012;
  return 0.9 * (large * (1.0 - 0.65 * maria) + 0.8 * medium + 0.7 * small) + regolith;
}

struct ImpactMarks {
  float height;
  float ejecta;
  float shade;
  float glow;
};

ImpactMarks impactMarks(vec3 p, float baseHeight) {
  ImpactMarks marks = ImpactMarks(baseHeight, 0.0, 0.0, 0.0);
  for (int index = 0; index < MAX_IMPACTS; index++) {
    if (float(index) >= uImpactCount) {
      break;
    }
    vec4 impact = uImpacts[index];
    float age = uTime - impact.w;
    if (age < 0.0) {
      continue;
    }
    vec3 center = impact.xyz;
    float seed = hash13(center * 91.7);
    float radius = mix(0.07, 0.14, seed);
    vec3 offset = p - center;
    float reach = length(offset) / radius;
    if (reach > 8.0) {
      continue;
    }
    float grow = smoothstep(0.0, 0.09, age);
    float floorMask = smoothstep(1.15, 0.55, reach) * grow;
    marks.height = marks.height * (1.0 - 0.7 * floorMask) + craterProfile(reach) * radius * 0.95 * grow;

    vec3 helper = mix(vec3(0.0, 1.0, 0.0), vec3(1.0, 0.0, 0.0), step(0.9, abs(center.y)));
    vec3 tangent = normalize(cross(center, helper));
    vec3 bitangent = cross(center, tangent);
    float angle = atan(dot(offset, bitangent), dot(offset, tangent));
    vec3 around = vec3(cos(angle), sin(angle), 0.0);
    float rays = smoothstep(0.52, 0.82, valueNoise(around * 4.5 + center * 37.0 + seed * 11.0));
    float rayReach = exp(-(reach - 1.0) * (0.45 + 0.35 * seed)) * smoothstep(0.95, 1.35, reach);
    float blanket = exp(-pow((reach - 1.25) / 0.32, 2.0));
    float freshness = mix(0.35, 1.0, exp(-age / 9.0));
    marks.ejecta += (rays * rayReach + 0.55 * blanket) * freshness * grow;
    marks.shade += rayReach * (1.0 - rays) * freshness * grow;

    float flash = exp(-age * 16.0) * smoothstep(2.4, 0.0, reach);
    float wave = clamp(age / SHOCKWAVE_SECONDS, 0.0, 1.0);
    float front = 1.0 + 6.0 * (1.0 - pow(1.0 - wave, 3.0));
    float ring = exp(-pow((reach - front) / 0.45, 2.0)) * pow(1.0 - wave, 1.5);
    marks.glow += 1.4 * flash + 0.6 * ring;
  }
  return marks;
}

vec3 perturbNormal(vec3 position, vec3 normal, float height) {
  vec3 sigmaX = dFdx(position);
  vec3 sigmaY = dFdy(position);
  vec3 r1 = cross(sigmaY, normal);
  vec3 r2 = cross(normal, sigmaX);
  float determinant = dot(sigmaX, r1);
  vec2 slope = vec2(dFdx(height), dFdy(height));
  vec3 gradient = sign(determinant) * (slope.x * r1 + slope.y * r2);
  return normalize(abs(determinant) * normal - gradient);
}

${bayerGlsl}
void main() {
  vec3 p = normalize(vObjectPosition);
  float maria = smoothstep(0.47, 0.6, fbm(p * 1.7 + 4.0));
  float albedo = mix(1.0, 0.56, maria) * mix(0.9, 1.08, fbm(p * 9.0 + 1.3));

  vec3 geometryNormal = normalize(vWorldNormal);
  ImpactMarks marks = impactMarks(p, surfaceHeight(p, maria));
  albedo = albedo * (1.0 - 0.35 * min(marks.shade, 1.0)) + 0.5 * marks.ejecta;
  vec3 normal = perturbNormal(vWorldPosition, geometryNormal, marks.height);

  vec3 light = normalize(uLightDir);
  vec3 view = normalize(cameraPosition - vWorldPosition);
  float facing = dot(geometryNormal, light);
  float incidence = max(dot(normal, light), 0.0);
  float emergence = max(dot(normal, view), 0.0);
  float lommel = 2.0 * incidence / (incidence + emergence + 0.001);
  float terminator = smoothstep(-0.05, 0.32, facing);
  float lit = mix(incidence, lommel * 0.5, 0.25) * terminator;

  float limb = 1.0 - max(dot(geometryNormal, view), 0.0);
  float rim = pow(limb, 4.0) * smoothstep(0.0, 0.6, facing) * 0.3;
  float earthshine = 0.03 * (1.0 - terminator);

  float tone = albedo * (lit + earthshine) + rim;
  tone = smoothstep(0.02, 0.92, tone) + marks.glow;

  float cellSize = max(uPixelSize * uDpr, 1.0);
  float threshold = bayer8(gl_FragCoord.xy / cellSize) + 1.0 / 128.0;
  float grain = (hash12(floor(gl_FragCoord.xy) + floor(uTime * 24.0) * vec2(13.7, 7.3)) - 0.5) * uGrain * 0.36;
  float paper = step(threshold, tone + grain * step(0.002, tone));

  gl_FragColor = vec4(mix(uInk, uPaper, paper), 1.0);
  #include <colorspace_fragment>
}
`;

const createUniforms = (): LunarDitherUniforms => ({
  uCraterScale: { value: lunarDitherDefaults.craterScale },
  uDpr: { value: 1 },
  uGrain: { value: lunarDitherDefaults.grain },
  uImpactCount: { value: 0 },
  uImpacts: {
    value: Array.from(
      { length: lunarDitherDefaults.maxImpacts },
      () => new Vector4()
    ),
  },
  uInk: { value: new Color(lunarDitherDefaults.ink) },
  uLightDir: { value: new Vector3(-0.5, 0.2, 0.8).normalize() },
  uPaper: { value: new Color(lunarDitherDefaults.paper) },
  uPixelSize: { value: lunarDitherDefaults.pixelSize },
  uTime: { value: 0 },
});

export class LunarDitherMaterial extends ShaderMaterial {
  declare uniforms: LunarDitherUniforms;
  private nextImpact = 0;

  constructor() {
    super({
      defines: {
        MAX_IMPACTS: lunarDitherDefaults.maxImpacts,
        SHOCKWAVE_SECONDS: impactTiming.shockwave.toFixed(2),
      },
      fragmentShader,
      toneMapped: false,
      uniforms: createUniforms(),
      vertexShader,
    });
  }

  setImpactCapacity(capacity: number) {
    const { uImpacts } = this.uniforms;
    if (uImpacts.value.length === capacity) {
      return;
    }
    uImpacts.value = Array.from({ length: capacity }, () => new Vector4());
    this.defines.MAX_IMPACTS = capacity;
    this.needsUpdate = true;
    this.clearImpacts();
  }

  addImpact(direction: Vector3, birth: number) {
    const { uImpactCount, uImpacts } = this.uniforms;
    const capacity = uImpacts.value.length;
    uImpacts.value[this.nextImpact]?.set(
      direction.x,
      direction.y,
      direction.z,
      birth
    );
    this.nextImpact = (this.nextImpact + 1) % capacity;
    uImpactCount.value = Math.min(uImpactCount.value + 1, capacity);
  }

  clearImpacts() {
    this.nextImpact = 0;
    this.uniforms.uImpactCount.value = 0;
  }
}

import {
  DynamicDrawUsage,
  InstancedMesh,
  Matrix4,
  PlaneGeometry,
  ShaderMaterial,
  Vector3,
} from "three";
import type { Object3D } from "three";

import { bayerGlsl, impactTiming } from "./lunar-dither-material";
import type { LunarDitherUniforms } from "./lunar-dither-material";

const streakCapacity = 12;
const streakWidth = 0.07;
const tailShare = 0.42;
const approachDistance = 1.7;

const vertexShader = `
varying vec2 vUv;

void main() {
  vUv = uv;
  vec4 local = vec4(position, 1.0);
  #ifdef USE_INSTANCING
  local = instanceMatrix * local;
  #endif
  gl_Position = projectionMatrix * modelViewMatrix * local;
}
`;

const fragmentShader = `
uniform vec3 uPaper;
uniform float uPixelSize;
uniform float uDpr;

varying vec2 vUv;

${bayerGlsl}

void main() {
  float across = abs(vUv.y - 0.5) * 2.0;
  float body = 1.0 - smoothstep(0.15, 1.0, across / max(vUv.x, 0.2));
  float coverage = (0.15 + 0.85 * vUv.x) * body * 1.2;
  float cellSize = max(uPixelSize * uDpr, 1.0);
  if (coverage < bayer8(gl_FragCoord.xy / cellSize) + 1.0 / 128.0) {
    discard;
  }
  gl_FragColor = vec4(uPaper, 1.0);
  #include <colorspace_fragment>
}
`;

interface Flight {
  launch: number;
  origin: Vector3;
  target: Vector3;
}

export class MeteorStreaks {
  readonly mesh: InstancedMesh;
  private readonly flights: Flight[] = [];
  private readonly matrix = new Matrix4();
  private readonly head = new Vector3();
  private readonly tail = new Vector3();
  private readonly end = new Vector3();
  private readonly axis = new Vector3();
  private readonly side = new Vector3();
  private readonly depth = new Vector3();
  private readonly middle = new Vector3();

  constructor(uniforms: LunarDitherUniforms) {
    const material = new ShaderMaterial({
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      uniforms: {
        uDpr: uniforms.uDpr,
        uPaper: uniforms.uPaper,
        uPixelSize: uniforms.uPixelSize,
      },
      vertexShader,
    });
    this.mesh = new InstancedMesh(
      new PlaneGeometry(1, 1),
      material,
      streakCapacity
    );
    this.mesh.instanceMatrix.setUsage(DynamicDrawUsage);
    this.mesh.frustumCulled = false;
    this.mesh.count = 0;
    this.mesh.renderOrder = 1;
  }

  launch(target: Vector3, hit: Vector3, toCamera: Vector3, now: number) {
    const sideways = this.side
      .set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
      .projectOnPlane(toCamera)
      .normalize();
    const direction = this.axis
      .copy(hit)
      .normalize()
      .multiplyScalar(0.55)
      .addScaledVector(toCamera, 0.45)
      .addScaledVector(sideways, 1.1)
      .normalize();
    if (this.flights.length >= streakCapacity) {
      this.flights.shift();
    }
    this.flights.push({
      launch: now,
      origin: hit.clone().addScaledVector(direction, approachDistance),
      target: target.clone(),
    });
  }

  advance(now: number, moon: Object3D, cameraPosition: Vector3) {
    let drawn = 0;
    for (const flight of this.flights) {
      const progress = (now - flight.launch) / impactTiming.flight;
      if (progress < 0 || progress >= 1) {
        continue;
      }
      this.end.copy(flight.target);
      moon.localToWorld(this.end);
      this.head.lerpVectors(flight.origin, this.end, progress);
      this.tail.lerpVectors(
        flight.origin,
        this.end,
        Math.max(progress - tailShare, 0)
      );
      this.axis.subVectors(this.head, this.tail);
      const length = this.axis.length();
      if (length < 1e-4) {
        continue;
      }
      this.middle.addVectors(this.head, this.tail).multiplyScalar(0.5);
      this.depth.subVectors(cameraPosition, this.middle).normalize();
      this.side
        .crossVectors(this.depth, this.axis)
        .normalize()
        .multiplyScalar(streakWidth);
      this.depth.crossVectors(this.axis, this.side).normalize();
      this.matrix
        .makeBasis(this.axis, this.side, this.depth)
        .setPosition(this.middle);
      this.mesh.setMatrixAt(drawn, this.matrix);
      drawn += 1;
    }
    const lastLaunch = now - impactTiming.flight;
    while (
      this.flights.length > 0 &&
      (this.flights[0]?.launch ?? 0) < lastLaunch
    ) {
      this.flights.shift();
    }
    this.mesh.count = drawn;
    this.mesh.visible = drawn > 0;
    this.mesh.instanceMatrix.needsUpdate = drawn > 0;
  }

  clear() {
    this.flights.length = 0;
    this.mesh.count = 0;
    this.mesh.visible = false;
  }

  dispose() {
    this.mesh.geometry.dispose();
    const { material } = this.mesh;
    if (!Array.isArray(material)) {
      material.dispose();
    }
    this.mesh.dispose();
  }
}

"use client";

import { Canvas } from "@react-three/fiber";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

import { cn } from "@/lib/utils";
import { useInView } from "@/registry/ivan/hooks/use-in-view";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { useWebGLSupport } from "@/registry/ivan/hooks/use-webgl-support";

export interface CanvasStageProps {
  ground: string;
  label: string;
  paused: boolean;
  fallback: ReactNode;
  antialias?: boolean;
  camera?: ComponentProps<typeof Canvas>["camera"];
  className?: string;
  children: (isAnimating: boolean) => ReactNode;
}

interface ImageFallbackProps {
  src: string;
  focus: { x: number; y: number };
}

export const ImageFallback = ({ src, focus }: ImageFallbackProps) => (
  <div
    aria-hidden
    className="absolute inset-0 grayscale"
    style={{
      backgroundImage: `url(${JSON.stringify(src)})`,
      backgroundPosition: `${focus.x * 100}% ${focus.y * 100}%`,
      backgroundSize: "cover",
    }}
  />
);

export const CanvasStage = ({
  ground,
  label,
  paused,
  fallback,
  antialias = false,
  camera,
  className,
  children,
}: CanvasStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const hasWebGL = useWebGLSupport();
  const isInView = useInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isAnimating = isInView && !prefersReducedMotion && !paused;

  return (
    <figure
      aria-label={label}
      className={cn(
        "relative m-0 aspect-4/3 w-full overflow-hidden",
        className
      )}
      ref={frame}
      style={{ backgroundColor: ground }}
    >
      {hasWebGL ? (
        <Canvas
          aria-hidden
          camera={camera}
          dpr={[1, 1.75]}
          frameloop={isAnimating ? "always" : "demand"}
          gl={{
            alpha: true,
            antialias,
            powerPreference: "high-performance",
          }}
        >
          {children(isAnimating)}
        </Canvas>
      ) : (
        fallback
      )}
    </figure>
  );
};

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useSyncExternalStore } from "react";

let cachedSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedSupport !== null) {
    return cachedSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedSupport = context !== null;
  } catch {
    cachedSupport = false;
  }
  return cachedSupport;
};

const subscribe = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerSnapshot = () => true;

export const useWebGLSupport = () =>
  useSyncExternalStore(subscribe, detectWebGL, getServerSnapshot);

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

export const useInView = (
  target: RefObject<Element | null>,
  rootMargin = "10% 0px"
) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [rootMargin, target]);

  return isInView;
};
